90 |         let shared_task = self
91 |             .shared_task
92 |             .get_or_insert_with(|| {
93 |                 let task = self.task.take();
94 |                 async move {
95 |                     let Some(task) = task else {
96 |                         return Err(Arc::new(Error::internal(
97 |                             "missing read task while splitting a merged stream".to_string(),
